74	    @Column(name = "customer_code")
75	    private String customerCode;
76	
77	    @Column(name = "household_id")
78	    private String householdId;
79	
80	    @Column(name = "namesake_count")
81	    private Integer namesakeCount;
82	
83	    @Column(name = "bulk_signup_warning")
84	    private Boolean bulkSignupWarning;
85	
86	    @Column(name = "household_size")
87	    private Integer householdSize;
88	
89	    @Column(name = "possible_duplicate")
90	    private Boolean possibleDuplicate;
91	
92	    @Column(name = "possible_duplicate_of")
93	    private Integer possibleDuplicateOf;
94	
95	    @Column(name = "deleted")
96	    private boolean deleted;
97	
98	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
99	    private Set<Pet> pets;
100	
101	    public String getTitle() {
102	        return this.title;
103	    }
104	
105	    public void setTitle(String title) {
106	        this.title = title;
107	    }
108	
109	    /**
110	     * The owner's salutation: the optional {@link #title} (MR/MRS/MS/DR) followed by a single space
111	     * and the last name, or just the last name when no title was supplied. A blank title is treated
112	     * as absent.
113	     *
114	     * @return the composed salutation
115	     */
116	    @Transient
117	    public String getSalutation() {
118	        if (this.title == null || this.title.isBlank()) {
119	            return this.getLastName();
120	        }
121	        return this.title + " " + this.getLastName();
122	    }
123	
124	    public String getAddress() {
125	        return this.address;
126	    }
127	
128	    public void setAddress(String address) {
129	        this.address = address;
130	    }
131	
132	    public String getAddressLine1() {
133	        return this.addressLine1;
134	    }
135	
136	    public void setAddressLine1(String addressLine1) {
137	        this.addressLine1 = addressLine1;
138	    }
139	
140	    public String getAddressLine2() {
141	        return this.addressLine2;
142	    }
143	
144	    public void setAddressLine2(String addressLine2) {
145	        this.addressLine2 = addressLine2;
146	    }
