164	    public String getTelephone() {
165	        return this.telephone;
166	    }
167	
168	    public void setTelephone(String telephone) {
169	        this.telephone = telephone;
170	    }
171	
172	    /**
173	     * The known E.164 country calling codes used to split the stored telephone into its country
174	     * code and national digits when formatting {@link #getTelephoneDisplay()}. Ordered
175	     * longest-first so the most specific code wins; this mirrors the codes the application
176	     * recognises elsewhere (Australia {@code '+61'} and the NANP {@code '+1'}).
177	     */
178	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
179	
180	    /**
181	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
182	     * national digits grouped in threes from the left and separated by spaces. So the stored
183	     * {@code '+61412345678'} is displayed as {@code '+61 412 345 678'}. The raw {@link #telephone}
184	     * itself is left in E.164 form. A {@code null} telephone yields {@code null}, and a value not in
185	     * E.164 form (no leading {@code '+'}) is returned unchanged.
186	     *
187	     * @return the human-formatted telephone, or {@code null} when no telephone is stored
188	     */
189	    @Transient
190	    public String getTelephoneDisplay() {
191	        if (this.telephone == null || !this.telephone.startsWith("+")) {
192	            return this.telephone;
193	        }
194	        String allDigits = this.telephone.substring(1);
195	        if (allDigits.isEmpty()) {
196	            return this.telephone;
197	        }
198	        String countryCode = null;
199	        for (String code : KNOWN_COUNTRY_CODES) {
200	            if (allDigits.startsWith(code)) {
201	                countryCode = code;
202	                break;
203	            }
204	        }
205	        if (countryCode == null) {
206	            countryCode = allDigits.substring(0, 1);
207	        }
208	        String national = allDigits.substring(countryCode.length());
209	        StringBuilder display = new StringBuilder("+").append(countryCode);
210	        for (int i = 0; i < national.length(); i += 3) {
211	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
212	        }
213	        return display.toString();
214	    }
