224	    public LocalDate getRegistrationDate() {
225	        return this.registrationDate;
226	    }
227	
228	    public void setRegistrationDate(LocalDate registrationDate) {
229	        this.registrationDate = registrationDate;
230	    }
231	
232	    public LocalDate getBirthDate() {
233	        return this.birthDate;
234	    }
235	
236	    public void setBirthDate(LocalDate birthDate) {
237	        this.birthDate = birthDate;
238	    }
239	
240	    /**
241	     * Derives the owner's age band from a birth date, computed against the reference date
242	     * (the registration date): {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
243	     * and {@code 'SENIOR'} at 65 or older. The completed-years age is the whole number of years
244	     * between the birth date and the reference date. Returns {@code null} when no birth date is
245	     * supplied. When the reference date is absent the current server date is used.
246	     *
247	     * @param birthDate the owner's date of birth, or {@code null} when absent
248	     * @param reference the date to compute the age against (the registration date), may be {@code null}
249	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date
250	     */
251	    public static String ageBandOf(LocalDate birthDate, LocalDate reference) {
252	        if (birthDate == null) {
253	            return null;
254	        }
255	        LocalDate asOf = reference != null ? reference : LocalDate.now();
256	        int years = java.time.Period.between(birthDate, asOf).getYears();
257	        if (years < 18) {
258	            return "MINOR";
259	        }
260	        if (years < 65) {
261	            return "ADULT";
262	        }
263	        return "SENIOR";
264	    }
265	
266	    /**
267	     * Whether the owner's tenure — the whole number of days from the registration date to the
268	     * current server date — exceeds one year (strictly more than 365 days). This gates the top
269	     * membership level: only an owner past a full year of tenure can reach level 4. A {@code null}
270	     * registration date, or one in the future, counts as zero tenure and so never exceeds the
271	     * threshold, which is why a newly created owner (zero tenure) can never exceed level 3.
272	     *
273	     * @param registrationDate the date the owner registered, or {@code null} when absent
274	     * @return {@code true} when the tenure is strictly greater than 365 days
275	     */
276	    public static boolean tenureExceedsOneYear(LocalDate registrationDate) {
277	        if (registrationDate == null) {
278	            return false;
279	        }
280	        return java.time.temporal.ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365;
281	    }
282	
283	    /**
284	     * The owner's membership points, accumulated from the membership factors. Points start at 0 and
285	     * gain 2 when an email address is present, 1 when the owner has no namesakes (namesakeCount is
286	     * 0), 2 for a household of 3 or more members, and 3 when the owner's tenure exceeds one year.
287	     *
288	     * @param owner the owner to score
289	     * @return the total membership points (never negative)
290	     */
291	    public static int membershipPoints(Owner owner) {
292	        int points = 0;
293	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
294	            points += 2;
295	        }
296	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
297	            points += 1;
298	        }
299	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
300	            points += 2;
301	        }
302	        if (tenureExceedsOneYear(owner.getRegistrationDate())) {
303	            points += 3;
304	        }
305	        return points;
306	    }
307	
308	    /**
309	     * Maps membership points to the numeric membership level: 1 for 0-1 points, 2 for 2-3, 3 for
310	     * 4-5, and 4 for 6 or more.
311	     *
312	     * @param points the owner's membership points
313	     * @return the membership level, from 1 to 4
314	     */
315	    public static int membershipLevel(int points) {
316	        if (points <= 1) {
317	            return 1;
318	        }
319	        if (points <= 3) {
320	            return 2;
321	        }
322	        if (points <= 5) {
323	            return 3;
324	        }
325	        return 4;
326	    }
