341	        this.householdId = householdId;
342	    }
343	
344	    public Integer getNamesakeCount() {
345	        return this.namesakeCount;
346	    }
347	
348	    public void setNamesakeCount(Integer namesakeCount) {
349	        this.namesakeCount = namesakeCount;
350	    }
351	
352	    public Boolean getBulkSignupWarning() {
353	        return this.bulkSignupWarning;
354	    }
355	
356	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
357	        this.bulkSignupWarning = bulkSignupWarning;
358	    }
359	
360	    public Integer getHouseholdSize() {
361	        return this.householdSize;
362	    }
363	
364	    public void setHouseholdSize(Integer householdSize) {
365	        this.householdSize = householdSize;
366	    }
367	
368	    public Boolean getPossibleDuplicate() {
369	        return this.possibleDuplicate;
370	    }
371	
372	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
373	        this.possibleDuplicate = possibleDuplicate;
374	    }
375	
376	    public Integer getPossibleDuplicateOf() {
377	        return this.possibleDuplicateOf;
378	    }
379	
380	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
381	        this.possibleDuplicateOf = possibleDuplicateOf;
382	    }
383	
384	    public boolean isDeleted() {
385	        return this.deleted;
386	    }
387	
388	    public void setDeleted(boolean deleted) {
389	        this.deleted = deleted;
390	    }
391	
392	    /**
393	     * The single derived key used for all duplicate detection, formatted
394	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
395	     * duplicates only when their whole identity keys are equal; because the telephone is part
396	     * of the key, two members of the same household with different telephones have different
397	     * keys and are both allowed.
398	     *
399	     * @return the derived identity key
400	     */
401	    @Transient
402	    public String getIdentityKey() {
403	        return (this.telephone == null ? "" : this.telephone) + "|"
404	            + (this.email == null ? "" : this.email) + "|"
405	            + (this.householdId == null ? "" : this.householdId);
406	    }
407	
408	    /**
409	     * A single Luhn check digit (0-9) computed over the digits contained in the
410	     * {@code customerCode}. Non-digit characters (such as the letter prefixes and the
411	     * separators) are ignored; a {@code null} customer code is treated as having no digits.
412	     *
413	     * @return the Luhn check digit for the customer code
414	     */
415	    @Transient
416	    public int getCheckDigit() {
417	        String source = this.customerCode == null ? "" : this.customerCode;
418	        int sum = 0;
419	        boolean dbl = true;
420	        for (int i = source.length() - 1; i >= 0; i--) {
421	            char c = source.charAt(i);
422	            if (c < '0' || c > '9') {
423	                continue;
424	            }
425	            int d = c - '0';
426	            if (dbl) {
427	                d *= 2;
428	                if (d > 9) {
429	                    d -= 9;
430	                }
431	            }
432	            sum += d;
433	            dbl = !dbl;
434	        }
435	        return (10 - (sum % 10)) % 10;
436	    }
437	
438	    protected Set<Pet> getPetsInternal() {
439	        if (this.pets == null) {
440	            this.pets = new HashSet<>();
441	        }
442	        return this.pets;
443	    }
444	
445	    protected void setPetsInternal(Set<Pet> pets) {
446	        this.pets = pets;
447	    }
448	
449	    public List<Pet> getPets() {
450	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
451	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
452	        return Collections.unmodifiableList(sortedPets);
453	    }
454	
455	    public void setPets(List<Pet> pets) {
456	        this.pets = new HashSet<>(pets);
457	    }
458	
459	    public void addPet(Pet pet) {
460	        getPetsInternal().add(pet);
461	        pet.setOwner(this);
462	    }
463	
464	    /**
465	     * Return the Pet with the given name, or null if none found for this Owner.
466	     *
467	     * @param name to test
468	     * @return true if pet name is already in use
469	     */
470	    public Pet getPet(String name) {
471	        return getPet(name, false);
472	    }
473	
474	    /**
475	     * Return the Pet with the given name, or null if none found for this Owner.
476	     *
477	     * @param name to test
478	     * @return true if pet name is already in use
479	     */
480	    public Pet getPet(String name, boolean ignoreNew) {
481	        name = name.toLowerCase();
482	        for (Pet pet : getPetsInternal()) {
483	            if (!ignoreNew || !pet.isNew()) {
484	                String compName = pet.getName();
485	                compName = compName.toLowerCase();
486	                if (compName.equals(name)) {
487	                    return pet;
488	                }
489	            }
490	        }
491	        return null;
492	    }
493	
494	    public Pet getPet(Integer petId) {
495	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
496	    }
497	
498	    @Override
499	    public String toString() {
500	        return new ToStringCreator(this)
501	
502	            .append("id", this.getId())
503	            .append("new", this.isNew())
504	            .append("lastName", this.getLastName())
505	            .append("firstName", this.getFirstName())
506	            .append("address", this.address)
507	            .append("city", this.city)
508	            .append("telephone", this.telephone)
509	            .toString();
510	    }
511	}
